/* @lc app=leetcode id=909 lang=kotlin */ class Solution { fun snakesAndLadders(board: Array<IntArray>): Int = board.size.let { n -> BooleanArray(n * n + 1).also { it[1] = true }.let { seen -> generateSequence(listOf(1)) { f -> f.flatMap { s -> (s + 1..minOf(s + 6, n * n)).map { t -> ((t - 1) / n).let { r -> board[n - 1 - r][if (r % 2 == 0) (t - 1) % n else n - 1 - (t - 1) % n] }.let { v -> if (v == -1) t else v } } }.filter { !seen[it] }.distinct().onEach { seen[it] = true }.takeIf { it.isNotEmpty() } }.indexOfFirst { n * n in it } } } }